    t[77589] = "Сухопутна Акула G91"
    t[78877] = { name = "Слизька Грязьориба", fen = "Surprisingly well-preserved, but still pretty gross.", fua = "Напрочуд добре збережена, але все одно доволі огидна." }
    t[78880] = { name = "Солоне Осердя", fen = "Salt from the land, dredged up by the birth of a Weeping Horror.", fua = "Сіль землі, піднята на поверхню народженням Заплаканого Жахіття." }
    t[78881] = { name = "Шматок Стільника", fen = "A cross-section of dark honeycomb oozing with rich, golden honey.", fua = "Зріз темного стільника, що сочиться густим золотавим медом." }
    t[78911] = { name = "Цілі Залози Дряпуна", fen = "Disgusting to look at and yet the aroma from them is quite healing.", fua = "Огидні на вигляд, та аромат від них доволі цілющий." }
    t[78914] = { name = "Флакон Тигрячої Крові", fen = "A vial full of \"winning\".", fua = "Флакон, повний \"перемоги\"." }
    t[78917] = { name = "Накази Доджані", fen = "A series of crude drawings depict specific mogu artifacts that might be found at the ruins of Dojan.", fua = "Низка грубих малюнків зображає певні артефакти могу, які можна знайти в руїнах Доджана." }
    t[78918] = { name = "Листя Імператорського Лотоса", fen = "A pungent smell comes from these ugly leaves.", fua = "Від цього бридкого листя йде різкий запах." }
    t[78934] = { name = "Вода Молодості", fen = "Just touching the vial is enough to make you feel younger and more vibrant.", fua = "Сам лише дотик до флакона змушує вас почуватися молодшими й бадьорішими." }
    t[78941] = { name = "Величезне Ікло Пантери", fen = "A huge, sharp fang. Hopefully Ken-Ken's new plan is completely different from the last one.", fua = "Величезне гостре ікло. Сподіваймося, новий план Кен-Кена геть інакший, ніж попередній." }
    t[78942] = { name = "Слоїк Пігменту", fen = "Vivid pigment, appropriate for painting.", fua = "Яскравий пігмент, придатний для малювання." }
    t[78958] = { name = "Награбоване Добро Джину", fen = "A collection of vases, knick knacks, and other assorted goods held precious by those simple folk of the river.", fua = "Зібрання ваз, дрібничок та інших різноманітних речей, дорогих серцю того простого річкового народу." }
    t[78959] = { name = "Зміїне Яйце", fen = "Something living slumbers inside. Please handle it carefully.", fua = "Усередині дрімає щось живе. Будь ласка, поводьтеся з ним обережно." }
    t[78960] = { name = "Зелене Зміїне Яйце", fen = "What could be inside?", fua = "Що ж там усередині?" }
    t[78961] = { name = "Жовте Зміїне Яйце", fen = "What could be inside?", fua = "Що ж там усередині?" }
    t[78962] = { name = "Блакитне Зміїне Яйце", fen = "What could be inside?", fua = "Що ж там усередині?" }
    t[79010] = "Сніжна Лілія"
    t[79011] = "Блазнівський Ковпак"
    t[79025] = { name = "Гарпун Звивнолусків", fen = "The shoddy weapon will likely maim its target, not kill it.", fua = "Ця нікчемна зброя радше скалічить ціль, ніж уб'є." }
    t[79030] = { name = "Стільник", fen = "Golden, delicious honeycomb.", fua = "Золотавий, смачнючий стільник." }
    t[79046] = { name = "Цукровий Гольян", fen = "These small, glass-like fish are sweet to the taste and a favorite of the wild serpents.", fua = "Ці маленькі скляні рибки солодкі на смак і є улюбленцями диких зміїв." }
    t[79049] = { name = "Реліквія Зміїного Вершника", fen = "The dusty relic is covered with ancient text. Jenova Longeye at The Arboretum in The Jade Forest will want to see this.", fua = "Запорошену реліквію вкрито стародавнім текстом. Дженова Далекозора в Дендрарії в Нефритовому Лісі захоче на це поглянути." }
    t[79058] = { name = "Голова Темношкура", fen = "This face is worn with age and stares at you with lifeless, guilt-inducing eyes.", fua = "Це обличчя позначене віком і дивиться на вас неживими очима, що пробуджують почуття провини." }
    t[79059] = { name = "Цілий Панцир Черепахи", fen = "This shell escaped the encounter with you relatively unscathed.", fua = "Цей панцир пережив зустріч із вами відносно неушкодженим." }
    t[79067] = { name = "Вкрадене Яйце", fen = "A little scuffed but otherwise in good shape.", fua = "Трохи подряпане, але в цілому в гарному стані." }
    t[79101] = "Призматична Луска"
    t[79120] = { name = "Артефакт Могу", fen = "This seemingly simple relic is covered with dust, worn with age, and seethes with arcane power.", fua = "Ця на вигляд проста реліквія вкрита пилом, потерта від часу й вирує таємною силою." }
    t[79197] = { name = "Галявинний Світляк", fen = "If you were a fish, this would look absolutely mouthwatering.", fua = "Якби ви були рибою, це виглядало б страшенно апетитно." }
    t[79198] = { name = "Тонке Кров'яне Перо", fen = "Not only is it brightly colored, but the blood within the shaft should attract hungry fish.", fua = "Воно не лише яскраво забарвлене — кров усередині стрижня має приваблювати голодну рибу." }
    t[79199] = { name = "Голова Каламутнолуска", fen = "The eyes still glow faintly.", fua = "Очі досі ледь світяться." }
    t[79237] = { name = "Величезний Хвіст Кроколіска", fen = "There must be something in the water.", fua = "Мабуть, щось не те у воді." }
    t[79244] = { name = "М'ясо Газелі з Прекрасних Земель", fen = "Rare.", fua = "Рідкісне." }
    t[79246] = { name = "Ніжні Пелюстки Цвіту", fen = "Eternal Blossoms were once rumored to never wilt.  These petals most certainly do, but they have an undeniably alluring fragrance.", fua = "Подейкували, що вічні квіти ніколи не в'януть. Ці пелюстки точно в'януть, але мають беззаперечно привабливий аромат." }
    t[79250] = { name = "Свіжий Помплід", fen = "Tastes suspiciously like an apple.", fua = "На смак підозріло схожий на яблуко." }
    t[79251] = { name = "Тіньовий Пігмент", fen = "Commonly found when milling herbs native to Pandaria.", fua = "Часто трапляється під час подрібнення трав, що ростуть у Пандарії." }
    t[79252] = { name = "Отруєний Клинок Моґу", fen = "A dark oil coats this vicious looking blade.", fua = "Темна олія вкриває цей лиховісний клинок." }
    t[79253] = { name = "Туманний Пігмент", fen = "Rarely found when milling herbs native to Pandaria.", fua = "Зрідка трапляється під час подрібнення трав, що ростуть у Пандарії." }
    t[79254] = "Чорнило Снів"
    t[79255] = "Чорнило Зоряного Сяйва"
    t[79257] = "Рунний Сувій Стійкості III"
    t[79264] = { name = "Рубінова Скалка", fen = "This beautiful stone glitters. It would make a lovely gift for Haohan or Tina Mudclaw in the Valley of the Four Winds.", fua = "Цей чудовий камінь виблискує. Він став би гарним подарунком для Хаохана чи Тіни Грязькіготь у Долині Чотирьох Вітрів." }
    t[79265] = { name = "Блакитна Пір'їна", fen = "This soft feather is as blue as the sky. Old Hillpaw or Chee Chee, in the Valley of the Four Winds, may be interested in it.", fua = "Ця м'яка пір'їна синя, мов небо. Старого Пагорбала чи Чі-Чі в Долині Чотирьох Вітрів вона може зацікавити." }
    t[79266] = { name = "Нефритовий Кіт", fen = "An old relic, worn by time. Fish Fellreed or Ella, in the Valley of the Four Winds, may find this valuable.", fua = "Стара реліквія, потерта часом. Рибі Лютоочеретнику чи Еллі в Долині Чотирьох Вітрів вона може видатися цінною." }
    t[79267] = { name = "Гарне Яблуко", fen = "A juicy red apple. Sho or Jogu the Drunk, in the Valley of the Four Winds, may like this.", fua = "Соковите червоне яблуко. Шо чи Джогу П'яниці в Долині Чотирьох Вітрів воно може сподобатися." }
    t[79268] = { name = "Болотяна Лілія", fen = "Finding this rare flower is very lucky. Farmer Fung or Gina Mudclaw, in the Valley of the Four Winds, may like this item.", fua = "Знайти цю рідкісну квітку — велике щастя. Фермеру Фунгу чи Джині Грязькіготь у Долині Чотирьох Вітрів вона може сподобатися." }
    t[79269] = { name = "Болотяна Лілія", fen = "Finding this rare flower is very lucky. It would make a lovely present for Gina Mudclaw.", fua = "Знайти цю рідкісну квітку — велике щастя. З неї вийшов би чудовий подарунок для Джини Мадклоу." }
    t[79327] = "Релікт Сюеня"
    t[79328] = "Релікт Сюеня"
