    t[79332] = { name = "Звіт Розвідниці Вартових", fen = "This document is scrawled in the sentinel's flowing hand.", fua = "Цей документ написано плавним почерком вартової." }
    t[79333] = "Розписне Віяло"
    t[79334] = "Розписне Нефритове Віяло"
