    t[79340] = "Гравірований Посох Журавля"
    t[79341] = "Гравірований Посох Змія"
    t[79342] = "Посох з Примарного Заліза"
    t[79343] = "Гравірований Посох Тигра"
    t[79713] = { name = "Династична Табличка", fen = "Ancient text worn with time is etched on this tablet.", fua = "На цій табличці викарбувано стертий часом стародавній текст." }
    t[79731] = { name = "Сувій Мудрості", fen = "Used by Scribes in the creation of powerful objects.", fua = "Використовується писарями для створення могутніх предметів." }
    t[79740] = { name = "Простий Дерев'яний Посох", fen = "A plain wooden staff, used by scribes as a receptacle for inscriptions of great power.", fua = "Простий дерев'яний посох, який писарі використовують як вмістилище для написів великої сили." }
    t[79745] = { name = "Звіт Розвідника Сонцеходів", fen = "This document is scrawled in the sunwalker's flowing hand.", fua = "Цей документ написано плавним почерком сонцехода." }
    t[79753] = { name = "Ключ від Хвостокидів", fen = "This shiny metal key will free Bold Karasshi and Admiral Taylor.", fua = "Цей блискучий металевий ключ звільнить Карашші Зухвалого та адмірала Тейлора." }
    t[79806] = { name = "Стріла для Командирки Сє", fen = "These pandaren arrows are really sharp!", fua = "Ці пандаренські стріли справді гострі!" }
    t[79807] = { name = "Посох Мовця Води", fen = "An old, gnarled staff carved with words of power and adorned with assorted relics.", fua = "Старий, вузлуватий посох, вирізьблений словами сили та оздоблений різноманітними реліквіями." }
    t[79808] = { name = "Церемоніальна Роба", fen = "Silk robes that are covered with runes and symbols.", fua = "Шовкова роба, вкрита рунами й символами." }
    t[79809] = { name = "Нефритовий Вінець", fen = "A heavy headpiece carved from a single piece of jade.", fua = "Важкий головний убір, вирізьблений з єдиного шматка нефриту." }
    t[79810] = { name = "Чотки з Палісандра", fen = "Polished smooth by years of prayer.", fua = "Відполіровані до гладкості роками молитов." }
    t[79811] = { name = "Реліквія Склоплавців", fen = "Priceless.", fua = "Безцінна." }
    t[79824] = { name = "Вкрадений Овоч", fen = "Seems to be... mostly unharmed.", fua = "Здається... здебільшого неушкоджений." }
    t[79827] = { name = "Справжня Долинна Смаженина", fen = "Smells spicy.", fua = "Пахне гостро." }
    t[79828] = { name = "Статуетка Яка", fen = "For a hozen artifact, it's remarkably well-carved.", fua = "Як на артефакт гозенів, він напрочуд майстерно вирізьблений." }
    t[79833] = { name = "Тіньосвітний Трюфель", fen = "Its glow fades noticeably after being pulled from the ground.", fua = "Його сяйво помітно тьмяніє після того, як його викопали із землі." }
    t[79864] = { name = "Попелясточеревий Перець", fen = "Spicy enough to burn skin. Make sure you're wearing gloves!", fua = "Достатньо пекучий, щоб обпекти шкіру. Обов'язково вдягніть рукавички!" }
    t[79866] = { name = "Книга Легенд Кунзенів", fen = "An unbound collection of short stories, hozen proverbs, and offensive pictures.", fua = "Непереплетена збірка коротких оповідок, прислів'їв гозенів і непристойних малюнків." }
    t[79867] = { name = "Жирний Козячий Стейк", fen = "The Kunzen's livestock are nowhere near as gamy as the native goats of the Valley.", fua = "Худоба кунзенів і близько не така дичавіла на смак, як місцеві кози Долини." }
    t[79870] = { name = "Суп Ю-Пін", fen = "A soup made out of fish, apples, and herbs.", fua = "Суп із риби, яблук і трав." }
    t[79871] = { name = "Гострі Пельмені з Креветками", fen = "\"Spicy\" is an understatement.", fua = "\"Гострі\" - це ще м'яко сказано." }
    t[79875] = { name = "Пісня Долини", fen = "The paper is very old and fragile. The poem is written in strong, elegant brush strokes.", fua = "Папір дуже старий і крихкий. Вірш написано впевненими, витонченими мазками пензля." }
    t[79880] = { name = "Викрадені припаси", fen = "These supplies were slightly damaged in the fighting, but Merchant Shi should have no problem selling them.", fua = "Ці припаси трохи постраждали в бою, та купець Ші легко їх збуде." }
    t[79884] = { name = "Відро Слизької Води", fen = "The stench is unbearable.", fua = "Сморід нестерпний." }
    t[79894] = { name = "Печеня з Хвоста Мушана", fen = "Prepared the RIGHT way: on a mountain.", fua = "Приготовано ПРАВИЛЬНО: на горі." }
    t[79952] = { name = "Терпкі Хвоїнки Лісовика", fen = "These needles have a fresh pine scent to them.", fua = "Ці хвоїнки мають свіжий сосновий аромат." }
    t[80013] = { name = "Звіт Володарки Тіней Кірін", fen = "Everything appears in order. The request to strap poison bombs to the Hozen does strike you as odd.", fua = "Усе видається гаразд. Хоча прохання причепити отруйні бомби до гозенів здається вам дивним." }
    t[80014] = { name = "Звіт Ріветта Клатчпопа", fen = "Straight, to the point, and surprisingly optimistic.", fua = "Прямо, по суті й напрочуд оптимістично." }
    t[80015] = { name = "Звіт Шокії", fen = "Shokia's language, particularly in describing the Hozen, leaves little to be desired.", fua = "Мова Шокії, особливо коли вона описує гозенів, не залишає бажати кращого." }
    t[80061] = { name = "Звіт Ріко", fen = "While the report lacks any words you are able to make out a drawing of several slickies. You'll just have to fill in the gaps.", fua = "Хоча у звіті немає жодного зрозумілого слова, ви розрізняєте малюнок кількох слизняків. Доведеться вам самим домислити решту." }
    t[80116] = { name = "Надкушена Морква", fen = "Covered in sharp teeth marks. However, these marks look too small to have been made by virmen.", fua = "Укрита слідами гострих зубів. Утім, ці сліди надто дрібні, щоб їх лишили вірмени." }
    t[80122] = { name = "Павукокорінь", fen = "The thorny root stores a sour-tasting liquid.", fua = "Колюча коренева частина містить кислу на смак рідину." }
    t[80133] = { name = "Консервовані Овочі", fen = "Either they didn't like the taste, or they couldn't figure out how to get into the jar.", fua = "Або їм не сподобався смак, або вони не збагнули, як залізти в банку." }
    t[80134] = { name = "Необроблений Хризоберил", fen = "The gem slowly shifts from one color to the next as it absorbs the warmth from your hand.", fua = "Самоцвіт повільно змінює кольори, вбираючи тепло вашої руки." }
    t[80136] = { name = "Навоскована Дошка", fen = "A piece of solid bamboo wood.", fua = "Шматок міцного бамбукового дерева." }
    t[80137] = { name = "Награбований Перстень", fen = "Perfectly sized for a not-so-dainty pandaren finger.", fua = "Якраз на не такий уже й тендітний палець пандарена." }
    t[80138] = { name = "Вкрадений Вінець", fen = "Someone spent a lot of money on this.", fua = "Хтось витратив на це чимало грошей." }
    t[80139] = { name = "Викрадений Браслет", fen = "It's mostly silver, inlaid with gold and jade.", fua = "Здебільшого зі срібла, з інкрустацією золотом і нефритом." }
    t[80140] = { name = "Кровоцвіт", fen = "The plant leeches minerals out of the soil, leading to its dark crimson color.", fua = "Рослина витягує мінерали з ґрунту, від чого набуває темно-багряного кольору." }
    t[80141] = { name = "Печерна Лілія", fen = "This beautiful white flower thrives in dark, damp caves.", fua = "Ця прекрасна біла квітка квітне в темних вологих печерах." }
    t[80142] = { name = "Примарка", fen = "This rare mushroom gives off an eerie glow.", fua = "Цей рідкісний гриб випромінює моторошне сяйво." }
    t[80143] = { name = "Фіалковий Лишайник", fen = "A rare moss that grows at high altitudes.", fua = "Рідкісний мох, що росте на великій висоті." }
    t[80144] = { name = "Смачний Стейк на Кістці", fen = "A huge juicy slab of fatty meat.", fua = "Величезний соковитий шмат жирного м'яса." }
    t[80176] = { name = "Пошкоджена Водою Деталь", fen = "Slightly wet with what you hope is ocean water and not Hozen drool.", fua = "Трохи мокра від того, що ви сподіваєтесь є морською водою, а не слиною гозена." }
    t[80177] = { name = "Іржавий Стопорний Болт", fen = "Rust covered and almost unusable.", fua = "Укритий іржею і майже непридатний." }
    t[80213] = { name = "Плата Майстра Спецій Джин Джао", fen = "Jingles with coins.", fua = "Подзенькує монетами." }
    t[80214] = { name = "Плата Торговця Джамбізі", fen = "Smells of yak hair.", fua = "Пахне яковячою шерстю." }
    t[80215] = { name = "Плата Шинкарки Лей Лан", fen = "Filled with neatly-folded notes.", fua = "Наповнено акуратно складеними купюрами." }
    t[80216] = { name = "Плата Лоло Ліо", fen = "Crudely stuffed with crumpled notes.", fua = "Недбало напхано зім'ятими купюрами." }
    t[80222] = { name = "Бойовий Шолом Громового Короля", fen = "Polished to a sheen, the ancient helm bears not even a single scratch.", fua = "Відполірований до блиску, прадавній шолом не має жодної подряпини." }
    t[80223] = { name = "Призова Курка Старого Гілпава", fen = "Upon closer perusal... this IS a really nice chicken.", fua = "Придивившись уважніше... це СПРАВДІ чудова курка." }
    t[80227] = { name = "Коренеплід", fen = "Fresh from the farm.", fua = "Свіжий просто з ферми." }
    t[80228] = { name = "Зуб Велетенського Очеретяного Групера", fen = "It's pristine - suitable for use in a necklace or bracelet.", fua = "Бездоганний - підійде для намиста чи браслета." }
    t[80229] = { name = "Блакитна Прісноводна Перлина", fen = "It's blue.", fua = "Вона блакитна." }
    t[80230] = { name = "Чавунний Казан", fen = "Coated with years of yak grease.", fua = "Укритий шаром яковячого жиру, що накопичувався роками." }
    t[80231] = { name = "Золотовогняна Орхідея", fen = "You'll have to handle this delicately - it's quite fragile.", fua = "Поводитися з нею треба обережно - вона дуже тендітна." }
    t[80233] = { name = "Смажена Нога Рівнинного Сокола", fen = "Perfectly-cooked!", fua = "Приготовано бездоганно!" }
    t[80236] = { name = "Яблучно-Ягідна Самогонка", fen = "Best drank out of a paper bag.", fua = "Найкраще пити з паперового пакета." }
    t[80240] = { name = "Дивний Кулястий Камінь", fen = "A rough sphere carved from the native rock of Pandaria.", fua = "Груба сфера, витесана з пандарійського каменю." }
    t[80241] = { name = "Пам'ятка Мускусної Лапи", fen = "This simple bracelet has symbols of love and affection carved into it.", fua = "На цьому простому браслеті вирізьблено символи любові та ніжності." }
    t[80245] = { name = "М'ясні Шматочки Кун-Лай", fen = "It's not important where it came from. What's important is, it's meat - or passes for it, at least.", fua = "Не важливо, звідки це взялося. Важливо, що це м'ясо - або принаймні щось дуже схоже." }
    t[80260] = { name = "Доджанський Вугор", fen = "Probably best not to hold it for too long.", fua = "Мабуть, краще не тримати його надто довго." }
    t[80262] = { name = "Перстень Коханої", fen = "The intials J.H. are inscribed on the inside of the ring.", fua = "На внутрішньому боці персня вигравіювано ініціали Дж.Г." }
    t[80277] = { name = "М'ясо Зубчастого Морського Вушка", fen = "Seems kind of slimy.", fua = "Здається дещо слизьким." }
    t[80294] = { name = "Реліквія Моґу", fen = "This should fetch a few coins.", fua = "За неї має перепасти кілька монет." }
    t[80295] = { name = "Пакетик Насіння Зеленого Капустяного Качана", fen = "A paper envelope that rattles when you shake it.", fua = "Паперовий конверт, що деренчить, коли його трясеш." }
    t[80307] = { name = "Ґрумлячий Клунок", fen = "A collection of satchels, bags, boxes, and various parcels strewn together with string and rope weighing many more times that of a Grummle. The smell of incense and yak musk permeate every inch of these items.", fua = "Збіговисько торб, мішків, ящиків і всіляких пакунків, скріплених докупи нитками й мотузками, що важать у багато разів більше за самого ґрумля. Запах ладану й якового мускусу просякнув кожен сантиметр цих речей." }
    t[80310] = { name = "Срібний Бичок", fen = "The fish around here have very strange taste in food.", fua = "У тутешньої риби дуже дивні смаки щодо їжі." }
    t[80311] = { name = "Наповнена Пляшечка з Олією", fen = "A dark, foul-smelling substance sloshes about in this vial.", fua = "У цій пляшечці хлюпає темна смердюча речовина." }
    t[80314] = { name = "Легкорослий Зелений Капустяний Качан", fen = "Your first harvest! They won't fetch anything at the market, but their sentimental value is PRICELESS.", fua = "Твій перший урожай! На ринку за нього нічого не дадуть, але його сентиментальна цінність БЕЗЦІННА." }
    t[80315] = { name = "Викрадені припаси", fen = "This bundle contains mostly intact trade goods of various origin.", fua = "Цей пак містить здебільшого цілі ремісничі товари різного походження." }
    t[80316] = { name = "Щаслива Лапка Вірмена", fen = "This virmen foot has seen better days. The fur is worn and stained.", fua = "Ця лапка вірмена бачила кращі дні. Хутро потерте й заплямоване." }
    t[80317] = { name = "Щаслива Підкова Яка", fen = "This rusty old yak shoe doesn't feel very lucky...", fua = "Ця стара іржава підкова яка не здається аж надто щасливою..." }
    t[80318] = { name = "Щаслива Конюшина Чотирьох Вітрів", fen = "The leaves on this clover are mysteriously pristine.", fua = "Листочки цієї конюшини загадково бездоганні." }
    t[80319] = { name = "Щаслива «Золота» Монета", fen = "This coin has seen many journeys with Ji-Lu, but is almost unrecognizable due to tarnish.", fua = "Ця монета пройшла багато подорожей разом із Джі-Лу, але майже невпізнанна через потемніння." }
    t[80431] = "Складене Примарне Залізо"
    t[80433] = { name = "Дух Крові", fen = "Once awakened, the spirit will seek to bind itself to the tools of war.", fua = "Прокинувшись, дух прагнутиме зв'язатися зі знаряддями війни." }
    t[80437] = { name = "Панцирний Короп", fen = "Thick, heavy scales cover the fish.", fua = "Рибу вкривають товсті, важкі луски." }
    t[80511] = { name = "Кристал Веселіту", fen = "The sparkling crystals give off a faint hum.", fua = "Іскристі кристали видають ледь чутне гудіння." }
    t[80529] = { name = "Колючка Колючої Риби-Кулі", fen = "It's very difficult to hold.", fua = "Її дуже важко втримати." }
    t[80535] = { name = "Ключ від Кайданів Єті", fen = "This mishappen piece of metal should work to unfasten Old Poot Poot's shackles.", fua = "Цей кривий шматок металу має згодитися, щоб відімкнути кайдани старого Пут-Пута." }
    t[80598] = { name = "Прапор Жена", fen = "You have regained the shado-master's honor.", fua = "Ти відновив честь шадо-майстра." }
    t[80600] = { name = "Жало", fen = "Careful, it's very sharp.", fua = "Обережно, воно дуже гостре." }
    t[80677] = { name = "Смарагдове Хвостове Перо", fen = "A long, silky, dazzlingly green feather.", fua = "Довге, шовковисте, сліпучо-зелене перо." }
    t[80678] = { name = "Багряне Хвостове Перо", fen = "Not very heavy.", fua = "Не дуже важке." }
    t[80679] = { name = "Темне Хвостове Перо", fen = "The color shifts from indigo to violet as the sun reflects upon the quill.", fua = "Колір переходить від індиго до фіалкового, коли на пір'їні відбивається сонце." }
    t[80685] = { name = "Запасна Дошка", fen = "Lash enough of these together, and you'll have a pretty sturdy raft.", fua = "Зв'яжи їх удосталь докупи — і матимеш доволі надійний пліт." }
