    t[82299] = { name = "Закривавлене Лезо", fen = "Dried remenants of previous battles cover the blade of this weapon.", fua = "Засохлі рештки минулих битв укривають лезо цієї зброї." }
    t[82332] = "Батьків Арбалет"
    t[82342] = { name = "Фіолетовий Цитрон", fen = "The pollen from these flowers has a strangely acidic, citrusy smell.", fua = "Пилок цих квітів має дивно кислуватий, цитрусовий запах." }
    t[82353] = { name = "Зброя Сра'тіків", fen = "Recovered from Sra'thik mantid invaders.", fua = "Здобута в загарбників-мантидів Сра'тік." }
    t[82387] = { name = "Повний Мушановий Міхур", fen = "This seems like a GREAT thing to put in your bag.", fua = "Здається, це ЧУДОВА річ, щоб покласти в торбу." }
    t[82388] = { name = "Уламок Панцира Смердючого Кусаки", fen = "Tough, scaly, and regularly shaped. Perfect for mail armor.", fua = "Твердий, лускатий і рівної форми. Ідеальний для кольчуги." }
    t[82389] = { name = "Мао-Верба", fen = "The flowering branches are light, fluffy, and prickly to the touch.", fua = "Квітучі гілки легкі, пухнасті й колючі на дотик." }
    t[82393] = { name = "Відбиток Династії Шен", fen = "The text on the tablet was so worn it is hard to make out the symbols on the rubbing.", fua = "Текст на табличці настільки стертий, що символи на відбитку важко розрізнити." }
    t[82394] = { name = "Відбиток Династії Чан", fen = "Deeply carved symbols on the tablet have made this rubbing the easiest to read.", fua = "Глибоко вирізьблені символи на табличці зробили цей відбиток найлегшим для читання." }
    t[82395] = { name = "Відбиток Династії Вай", fen = "This rubbing contains only a small piece of the broken tablet's writing.", fua = "Цей відбиток містить лише невеликий уривок письмен зі зламаної таблички." }
