    t[83135] = { name = "Бурштинове Лезо", fen = "Mantid weaponry is characterized by large, curving blades of honed amber. Ideal for slicing, these weapons are lightweight and no less durable than those forged from metal.", fua = "Зброя мантидів вирізняється великими вигнутими лезами з відточеного бурштину. Ідеальна для розтинання, ця зброя легка й не менш міцна, ніж викувана з металу." }
