    t[86421] = { name = "Альманах Старого Тістла", fen = "A lifetime of study and notes.", fua = "Дослідження та нотатки за ціле життя." }
    t[86431] = { name = "Таємниці Штормстаутів", fen = "The brew recipes contained in the book are written in a code known only to the Stormstouts.", fua = "Рецепти пива в цій книзі записані шифром, відомим лише Штормстаутам." }
    t[86446] = { name = "Овечка", fen = "Bad sheep.", fua = "Погана вівця." }
    t[86476] = { name = "Ліхтар Короля-Чаклуна", fen = "The sorcerer king, Zian of the Endless Shadow used the light of this lantern to fuel his most powerful spells.", fua = "Король-чаклун Зіан Безкінечної Тіні живив світлом цього ліхтаря свої найпотужніші закляття." }
    t[86477] = { name = "Терези Божевільного Короля Менга", fen = "An obscure passage in an ancient text suggested that when Meng the Demented lost this balance, he lost his mind.", fua = "Незрозумілий уривок у стародавньому тексті натякає, що, втративши ці терези, Менг Схиблений втратив і розум." }
    t[86478] = { name = "«Наука Війни» Цянга", fen = "Qiang the Merciless was a master tactician and strategist.  A random quote from the Warlord King's treatise reads, \"Bones multiply as they are crushed.\"", fua = "Цянг Безжальний був майстром тактики та стратегії. Випадкова цитата з трактату короля-воєначальника промовляє: «Кістки множаться, коли їх трощать»." }
    t[86479] = { name = "Лук Прудкості Субетая", fen = "There were none so rapacious as the Bandit King, nor any whose bow proved so swift.", fua = "Не було нікого жадібнішого за короля-розбійника, ані нікого, чий лук був би таким прудким." }
