    t[86525] = { name = "Просочений Кров'ю Уламок Хітину", fen = "A fragment of Skeer the Bloodseeker's chitin, soaked in the blood of his enemies.", fua = "Уламок хітину Скіра Кровошукача, просочений кров'ю його ворогів." }
    t[86526] = "Амулет Хранителя Рою"
    t[86527] = "Клинок Отруєного Розуму"
    t[86529] = "Талісман Маніпулятора"
    t[86533] = { name = "Сяйливий Бурштин", fen = "The faint glow suggests this is not your ordinary piece of amber.", fua = "Слабке сяйво натякає, що це не звичайний шматок бурштину." }
    t[86542] = { name = "Летючий Тигровий Гурамі", fen = "A fish with wings?  That's a new one.", fua = "Риба з крилами? Оце вже щось новеньке." }
    t[86544] = { name = "Колючориб Альфа", fen = "Careful of the spines, they look like they could do some damage.", fua = "Стережіться голок: схоже, вони можуть добряче поранити." }
    t[86545] = { name = "Восьминіг-Імітатор", fen = "Even in death, this strange creature continues changing color to blend in with its environment.", fua = "Навіть по смерті ця дивна істота продовжує змінювати колір, щоб зливатися з довкіллям." }
    t[86558] = "Качалка"
    t[86559] = "Сковорода"
    t[86565] = { name = "Бойовий Ріг", fen = "Carried by Yaungol scouts to alert allies to impending attacks.", fua = "Яунгольські розвідники носять його, щоб попереджати союзників про близькі напади." }
    t[86567] = { name = "Яунгольські Вітряні Дзвіночки", fen = "Used by Yaungol medicine men to detect changes in the weather.", fua = "Використовуються яунгольськими знахарями, щоб виявляти зміни погоди." }
    t[86568] = "Мідний Компас Містера Смайта"
    t[86570] = { name = "Ящик з Викраденими Цуценятами", fen = "...and they eat puppies!", fua = "...і вони їдять цуценят!" }
    t[86571] = { name = "Камінь Зв'язування Канга", fen = "Mogu stonebinders use these rune-etched catalysts to transform flesh to stone.", fua = "Каменев'язи моґу використовують ці помережані рунами каталізатори, щоб обертати плоть на камінь." }
    t[86572] = { name = "Уламок Теракоти", fen = "Imbued with powerful Mogu magic.", fua = "Насичений могутньою магією могу." }
    t[86573] = { name = "Скалка Архікаменя", fen = "A fragment of unknown origin, seething with ancient power.", fua = "Уламок невідомого походження, що вирує прадавньою силою." }
    t[86575] = { name = "Чаша Таємниць", fen = "The rituals for desecrating a fallen opponent are a well-established part of Mogu culture.", fua = "Ритуали наруги над полеглим супротивником — усталена частина культури моґу." }
    t[86576] = { name = "Династія Сталі", fen = "The sword techniques of the Mantid are a carefully-guarded secret.", fua = "Техніки володіння мечем у мантидів — дбайливо оберігана таємниця." }
    t[86578] = { name = "Сигіл Вічного Воїна", fen = "Granted to Shek'zeer's elite guard for service to the Empress.", fua = "Наданий елітній варті Шек'зір за службу Імператриці." }
    t[86581] = { name = "Мушля Далеководдя", fen = "Inscribed with Jinyu runes that allow the user to understand the language of the waves.", fua = "Помережана рунами джинью, що дозволяють власнику розуміти мову хвиль." }
    t[86582] = { name = "Водяний Самоцвіт", fen = "Harvested from the maw of Gokk'lok.", fua = "Здобутий з пащі Ґокк'лока." }
    t[86583] = { name = "Бойовий Стяг Салінів", fen = "Stained with the blood of many unlucky adventurers.", fua = "Заплямований кров'ю багатьох безталанних шукачів пригод." }
    t[86584] = { name = "Загартований Панцир", fen = "Seems unfair.", fua = "Видається нечесним." }
    t[86585] = { name = "Золоте Руно", fen = "Considered a sign of wealth and status amongst the Saurok.", fua = "Серед сауроків вважається ознакою багатства й статусу." }
    t[86586] = "Флейта Пана з Пандарії"
    t[86587] = { name = "Насінина Спокійного Зростання", fen = "A vibrant life energy emanates from this seed.", fua = "Від цієї насінини струмує яскрава життєва енергія." }
    t[86588] = { name = "Пандаренський Запускач Феєрверків", fen = "Party over here!", fua = "Вечірка тут!" }
    t[86589] = { name = "Небесне Дзеркало Ай-Лі", fen = "Rimmed with an ever-shifting ring of clouds.", fua = "Облямоване вічно мінливим кільцем хмар." }
    t[86590] = "Сутність Вітерцю"
    t[86593] = "Пляжний М'яч Гозенів"
    t[86594] = { name = "Свисток Послужливого Віккі", fen = "Appears to have been heavily chewed on.", fua = "Схоже, його добряче пожували." }
    t[86596] = { name = "Рибальський Стілець Ната", fen = "It even has a beverage holder!", fua = "У ньому є навіть тримач для напоїв!" }
