    t[91814] = { name = "Бездоганна Золота Чубова Пір'їна", fen = "An immaculately clean, crisp, quill from a Child of Chi-Ji.", fua = "Бездоганно чисте, свіже перо Дитяти Чі-Джі." }
    t[91815] = { name = "Бездоганна Чорна Чубова Пір'їна", fen = "A jet-black feather, plucked from a Great Crane.", fua = "Чорна як смола пір'їна, вискубана у Великого Журавля." }
    t[91816] = { name = "Неушкоджений Окіст Яка", fen = "Fatty yak meat. What every tiger secretly wants.", fua = "Жирне м'ясо яка. Те, чого таємно прагне кожен тигр." }
    t[91817] = { name = "Смердюча Гнила Риба", fen = "The smell is... powerful.", fua = "Запах... потужний." }
    t[91823] = { name = "Оживлюваний Камінь", fen = "This stone seems to hum as you touch it.", fua = "Цей камінь немовби гуде, коли ви торкаєтеся його." }
    t[91834] = { name = "Стародавній Журавель Кривавого Вінця", fen = "The stunned body of a large, powerful crane.", fua = "Приголомшене тіло великого, могутнього журавля." }
    t[91835] = { name = "Старійшина Красарі", fen = "The stunned body of a large, powerful tiger.", fua = "Приголомшене тіло великого, могутнього тигра." }
    t[91836] = { name = "Колосальний Лещаклішень", fen = "The stunned body of a large, powerful crab.", fua = "Приголомшене тіло великого, могутнього краба." }
    t[91846] = { name = "Бочка \"Дистильованого\" Пального", fen = "A mixture of foul smelling sea water and fuel slosh around in the barrel.", fua = "У бочці хлюпає суміш смердючої морської води та пального." }
    t[91848] = { name = "Заряджена Брила Залізної Руди", fen = "The ore pulses with dark energy. This can't be good.", fua = "Руда пульсує темною енергією. Це не на добре." }
    t[91869] = { name = "Зіпсоване М'ясо Лещаклішня", fen = "A putrid odor exudes from the slimy piece of meat.", fua = "Від цього слизького шматка м'яса йде гнильний сморід." }
    t[91874] = { name = "Брила загадкового м'яса", fen = "A horrible smelling slime drips from the meat. It will take days to get the stench out of your bag.", fua = "З м'яса скрапує жахливо смердючий слиз. Минуть дні, перш ніж ти виведеш цей сморід зі своєї торби." }
    t[91904] = "Складаний Олень"
    t[91907] = { name = "Деревина Лев'ячого Десанту", fen = "Lumber recently harvested from the trees surrounding Lion's Landing - and recently abandoned by cowardly peasants!", fua = "Деревина, нещодавно зрубана з дерев навколо Лев'ячого Десанту — і нещодавно покинута боягузливими селянами!" }
    t[92072] = { name = "Кодекс Корунів", fen = "The leathery vellum shows a map of the northeastern Kun-Lai mountains. Ancient symbols of power, drawn in dark red ink, radiate outward from the map's center.", fua = "На шкірястому пергаменті зображено мапу північно-східних гір Кун-Лай. Стародавні символи влади, накреслені темно-червоним чорнилом, розходяться від центру мапи назовні." }
    t[92425] = { name = "Стародавня Таблиця Корунів", fen = "The stone tablet is covered in powerful mogu symbols.", fua = "Кам'яна таблиця вкрита могутніми могуанськими символами." }
    t[92474] = { name = "Особливо Воскові Вуха Альянсу", fen = "Sparkrocket Brand Lucky Ears - They're the Waxiest!", fua = "Щасливі Вуха від Іскрозапала — найвоскованіші!" }
    t[92484] = { name = "Запечатане Послання", fen = "It appears to be incredibly ordinary.", fua = "Виглядає неймовірно звичайним." }
    t[92493] = { name = "Підривний Капсуль Картелю Трюмних Вод", fen = "It's great for blasting!", fua = "Чудово годиться для підривів!" }
    t[92494] = "Уламок Пекельного Полум'я"
    t[92495] = "Уламок Нетерсторму"
    t[92496] = "Уламок Леза Гостряка"
    t[92497] = "Уламок Шадовмуну"
    t[92499] = { name = "Міцна Голка", fen = "A soothing aroma of pine drifts up from this stiff needle.", fua = "Від цієї твердої голки лине заспокійливий аромат сосни." }
    t[92510] = "Камінь Повернення Вол'джина"
    t[92539] = { name = "Неприборканий Бурштин", fen = "Plucked from the tail of a wild amber scorpion, this hardened gem gleams with an inner fire.", fua = "Вирваний із хвоста дикого бурштинового скорпіона, цей твердий самоцвіт сяє внутрішнім вогнем." }
    t[92556] = { name = "Підсилене Ядро Душі", fen = "This item is filled to the brim with arcane magic.", fua = "Цей предмет вщерть наповнений потаємною магією." }
    t[92557] = { name = "Металеве Вариво", fen = "Pairing the heat of a burning forge with the strong, stern tones of the earth, the flavor of this brew truly rocks.", fua = "Поєднуючи жар палахкого горна з міцними, суворими нотами землі, смак цього вариву справді карбований із каменю." }
    t[92560] = { name = "Голівка Молота", fen = "This brilliantly designed metal head shows almost no signs of age. It does have a number of food stains on it from the hozen that were using it as a dining table.", fua = "Ця майстерно виготовлена металева голівка майже не має слідів часу. Втім, на ній лишилося чимало плям від їжі — гозени використовували її як обідній стіл." }
    t[92561] = { name = "Руків'я Молота", fen = "This ornate rod has been passed down from generation to generation of hozen chiefs as a symbol of power.", fua = "Це оздоблене руків'я передавалося з покоління в покоління вождів гозенів як символ влади." }
    t[92562] = { name = "Гармонійна Мазь", fen = "You can almost feel this oil sing as you touch it, the very texture resonating through your fingers giving a sense of calm and relaxation.", fua = "Дотик до цієї олії майже відлунює співом, сама її текстура резонує крізь пальці, даруючи відчуття спокою та розслаблення." }
    t[92563] = { name = "Око Бурі", fen = "This naaru crystal contains immense power.", fua = "Цей кристал наару містить незмірну силу." }
    t[92704] = { name = "Прадавня Сутність Моґу", fen = "Heavier than it seems it should be - and cold to the touch.", fua = "Важча, ніж мала б бути - і холодна на дотик." }
    t[92708] = { name = "Пастка для Духів", fen = "A deactivated spirit trap. Hopefully the Reliquary can still extract whatever information they need from it.", fua = "Вимкнена пастка для духів. Сподіваймося, Реліквіарій ще зможе видобути з неї потрібні їм відомості." }
    t[92726] = "Рукавички Біпсі"
    t[92735] = { name = "Сутність Менґ-До", fen = "Incredibly heavy and hot to the touch.", fua = "Неймовірно важка й гаряча на дотик." }
    t[92736] = { name = "Сутність Ґен-Лі", fen = "These motes of dust move unpredictably, floating around your hands as you move them.", fua = "Ці порошинки рухаються непередбачувано, ширяючи навколо ваших рук, коли ви ними ворушите." }
    t[92747] = "Удосконалений Холодильний Блок"
    t[92754] = { name = "Вогняне Вино Рукіну", fen = "The white liquid gives off a pungent, stinging smell. A small taste turns your insides to fire, followed quickly by a warm, bubbly sensation in your head.", fua = "Біла рідина видає різкий, пекучий запах. Малий ковток обертає ваше нутро на вогонь, а слідом одразу приходить тепле, грайливе відчуття в голові." }
    t[92766] = "Маскування Кор'крона"
    t[92782] = { name = "Медальйон Непохитного Піхотинця", fen = "The blood of the footman it was taken from has left a permanent stain.", fua = "Кров піхотинця, з якого його зняли, залишила незмивну пляму." }
    t[92783] = { name = "Знак Загартованого Воїна", fen = "Several gash marks indicate that the grunt did not part with it willingly.", fua = "Кілька порізів свідчать, що воїн розлучився з ним не з власної волі." }
    t[92784] = { name = "Посібник Агента SI:7", fen = "A stolen manual detailing closely-guarded fighting techniques of the Alliance.", fua = "Викрадений посібник, що описує ретельно оберігані бойові техніки Альянсу." }
    t[92785] = { name = "Книга Болю Кор'кронів", fen = "Pilfered information on the Kor'kron's brutal techniques.", fua = "Викрадені відомості про жорстокі техніки Кор'кронів." }
    t[92786] = { name = "Відзнака Завоювання Альянсу", fen = "Torn from the grasp of a powerful alliance admiral.", fua = "Вирвана з рук могутнього адмірала Альянсу." }
    t[92787] = { name = "Відзнака Завоювання Орди", fen = "Torn from the grip of a powerful horde warleader.", fua = "Вирвана з рук могутнього воєначальника Орди." }
    t[92801] = { name = "Накази Корунів", fen = "These orders indicate that the Koruni have been called out of hiding in light of the resurrection of the Thunder King.", fua = "Ці накази вказують, що Корунів викликали зі сховку у світлі воскресіння Короля Грому." }
    t[92802] = { name = "Спадок Корунів", fen = "This scroll documents the history of the Korune clan, and their role in dark experiments during the days of the mogu empire.", fua = "Цей сувій оповідає історію клану Корунів та їхню роль у темних експериментах за часів імперії моґу." }
    t[92803] = { name = "Запечатаний Артефакт Корунів", fen = "This box clearly contains something of great power - and, perhaps, great danger.", fua = "Ця скриня вочевидь містить щось дуже могутнє - і, можливо, дуже небезпечне." }
    t[92804] = { name = "Потертий Щоденник", fen = "The pages of this dust-covered journal are ragged and hard to read.", fua = "Запилені сторінки цього щоденника пошарпані й важко читаються." }
