    t[93731] = { name = "Уламок Могуського Кодексу", fen = "Contains a portion of the Arcane Code blocking the entrance to the Zandalari Shipyard.", fua = "Містить частину таємного коду, що блокує вхід до Зандаларської Корабельні." }
    t[93733] = { name = "Маска Закликача Духів", fen = "Carefully carved, this mask surges with the power of the serpent Loa for which it represents.", fua = "Дбайливо вирізьблена, ця маска вирує силою змієподібного лоа, якого вона уособлює." }
    t[93734] = { name = "Маска Темного Містика", fen = "The magic within the mask is fickle. It honors only the strong and seeks to destroy the weak.", fua = "Магія всередині маски примхлива. Вона шанує лише сильних і прагне знищити слабких." }
    t[93735] = { name = "Ритуальний Артефакт", fen = "Who knows what dark magic this artifact was intended for...", fua = "Хтозна, для якої темної магії призначався цей артефакт..." }
    t[93736] = { name = "Клинок, Наповнений Силою Лоа", fen = "Specks of blood are barely visible through the ornate designs covering the blade and hilt of this weapon.", fua = "Цяточки крові ледь помітні крізь оздоблені візерунки, що вкривають клинок і руків'я цієї зброї." }
    t[93742] = "Зілля Зцілення"
    t[93792] = { name = "Голова Камергера", fen = "This mogu head continuously mocks you for your woefully inadequate stature.", fua = "Ця могуська голова без угаву глузує з вашого жалюгідно мізерного зросту." }
    t[93793] = { name = "Плече Камергера", fen = "One false move and this stone will crumble to dust in your hands.", fua = "Один невправний рух — і цей камінь розсиплеться на порох у ваших руках." }
    t[93794] = { name = "Посох Камергера", fen = "This stone weapon looks more ceremonial than functional.", fua = "Ця кам'яна зброя видається радше церемоніальною, ніж бойовою." }
    t[93795] = { name = "Волосся Камергера", fen = "There isn't much of this left.", fua = "Цього лишилося небагато." }
    t[93796] = { name = "Тулуб Камергера", fen = "For some reason, this is much lighter than it looks.", fua = "Чомусь він набагато легший, ніж видається на вигляд." }
    t[93805] = { name = "Розвідувальний Звіт Санріверів", fen = "Details Kirin Tor movements and numbers across the isle.", fua = "Описує переміщення та чисельність Кірін-Тор по всьому острову." }
